args.sparql:
SELECT DISTINCT ?burial ?burialLabel WHERE {
  dbr:Bayezid_II ?p ?burial .
  VALUES ?p { dbp:burialPlace dbp:placeofburial dbp:burial dbp:burials dbp:placeburial }
  OPTIONAL { ?burial rdfs:label ?burialLabel FILTER(lang(?burialLabel) = "en") }
}

SELECT DISTINCT ?place ?placeLabel WHERE {
  dbr:Bayezid_II ?p ?burial .
  VALUES ?p { dbp:burialPlace dbp:placeofburial dbp:burial dbp:burials dbp:placeburial }
  {
    FILTER(isIRI(?burial))
    BIND(?burial AS ?place)
  }
  UNION
  {
    FILTER(isLiteral(?burial))
    ?place rdfs:label ?placeLabelRaw .
    FILTER(lang(?placeLabelRaw) = "" || langMatches(lang(?placeLabelRaw), "en"))
    FILTER(
      CONTAINS(lcase(str(?placeLabelRaw)), lcase(str(?burial))) ||
      CONTAINS(lcase(str(?burial)), lcase(str(?placeLabelRaw)))
    )
  }
  OPTIONAL { ?place rdfs:label ?placeLabel FILTER(lang(?placeLabel) = "en") }
}

SELECT DISTINCT (dbr:Bayezid_II_Mosque AS ?place) ?lit WHERE {
  dbr:Bayezid_II dbp:burial ?lit .
  FILTER(CONTAINS(lcase(str(?lit)), "bayezid ii mosque"))
}

SELECT DISTINCT (dbr:Bayezid_II_Mosque AS ?place) ?lit WHERE {
  dbr:Bayezid_II dbp:burialPlace ?lit .
  FILTER(CONTAINS(lcase(str(?lit)), "bayezid ii mosque"))
}

SELECT DISTINCT (dbr:Bayezid_II_Mosque AS ?place) ?lit WHERE {
  dbr:Bayezid_II dbp:burialPlace ?lit .
  FILTER(CONTAINS(lcase(str(?lit)), "bayezid ii mosque"))
}

